export default function MarketBiasMascot({
  bias,
}: MarketBiasMascotProps) {
  return (
    <div className="atlas-mascot" data-bias={bias}>
      <style>{styles}</style>

      {bias === "BULLISH" && <Bull />}
      {bias === "BEARISH" && <Bear />}
      {bias === "NEUTRAL" && (
        <div className="atlas-mascot__pair">
          <Bull small />
          <Bear small />
        </div>
      )}
    </div>
  );
}

function Bull({ small = false }: { small?: boolean }) {
  return (
    <svg
      viewBox="0 0 608.4375 545.625"
      className={
        "atlas-mascot__bull" +
        (small ? " atlas-mascot__bull--small" : "")
      }
      role="img"
      aria-label="Oksemarked (bullish)"
    >
      <path d={BULL_PATH} />
    </svg>
  );
}

function Bear({ small = false }: { small?: boolean }) {
  return (
    <svg
      viewBox="0 0 744.09449 531.49606"
      className={
        "atlas-mascot__bear" +
        (small ? " atlas-mascot__bear--small" : "")
      }
      role="img"
      aria-label="Bjørnemarked (bearish)"
    >
      <g transform="translate(0,-520.86614)">
        <path d={BEAR_PATH} />
      </g>
    </svg>
  );
}

const styles = `
.atlas-mascot {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 120px;
  margin-top: 8px;
  border-radius: 16px;
}

/* subtle directional glow reinforcing the bias colour */
.atlas-mascot[data-bias="BULLISH"] {
  background: radial-gradient(ellipse at center, rgba(34, 197, 94, 0.13), transparent 70%);
}
.atlas-mascot[data-bias="BEARISH"] {
  background: radial-gradient(ellipse at center, rgba(239, 68, 68, 0.13), transparent 70%);
}
.atlas-mascot[data-bias="NEUTRAL"] {
  background: radial-gradient(ellipse at center, rgba(234, 179, 8, 0.10), transparent 70%);
}

.atlas-mascot__pair {
  display: flex;
  align-items: flex-end;
  gap: 10px;
}

.atlas-mascot svg {
  height: 108px;
  width: auto;
  overflow: visible;
}

.atlas-mascot__bull--small,
.atlas-mascot__bear--small {
  height: 74px;
}

/* --- colours --- */
.atlas-mascot__bull path { fill: #22c55e; stroke: none; }
.atlas-mascot__bear path { fill: #ef4444; stroke: none; }

/* --- bull: charge / bob up --- */
.atlas-mascot__bull {
  transform-box: fill-box;
  transform-origin: center;
  animation: atlas-bull-charge 1.9s ease-in-out infinite;
}
@keyframes atlas-bull-charge {
  0%, 100% { transform: translateY(4px) rotate(-1deg); }
  50%      { transform: translateY(-6px) rotate(1deg); }
}

/* --- bear: swipe / bob down --- */
.atlas-mascot__bear {
  transform-box: fill-box;
  transform-origin: center;
  animation: atlas-bear-swipe 2.1s ease-in-out infinite;
}
@keyframes atlas-bear-swipe {
  0%, 100% { transform: translateY(-4px) rotate(1deg); }
  50%      { transform: translateY(6px) rotate(-1deg); }
}

/* neutral pair: gentle idle bob, out of phase */
.atlas-mascot[data-bias="NEUTRAL"] .atlas-mascot__bull {
  animation-duration: 2.8s;
}
.atlas-mascot[data-bias="NEUTRAL"] .atlas-mascot__bear {
  animation-duration: 2.8s;
  animation-delay: 1.4s;
}

@media (prefers-reduced-motion: reduce) {
  .atlas-mascot__bull,
  .atlas-mascot__bear {
    animation: none;
  }
}
`;
